  const [showSurveyPanel, setShowSurveyPanel] = useState(false);
  const [isSurveyPanelCollapsed, setIsSurveyPanelCollapsed] = useState(false);
  const [isLeftSidebarCollapsed, setIsLeftSidebarCollapsed] = useState(true);

