	      chosenSource: chosenRedoSource,
	      chosenStack: chosenRedoSource === 'local annotation history'
	        ? 'localAnnotationRedo'
	        : chosenRedoSource === 'callout history' || chosenRedoSource === 'legacy history'
	          ? 'legacyRedoHistory'
	          : chosenRedoSource === 'Yjs/CRDT history'
