        setScaleWithViewportPreservation(targetScale, { preserveCenter: false });
        setTimeout(() => centerMatch({
          navigateFirst: true,
          behavior: 'smooth',
          retryBehavior: 'smooth'
        }), 180);
        setTimeout(() => centerMatch({
          navigateFirst: false,
          behavior: 'auto',
          retryBehavior: 'auto',
          skipIfClosePx: 24
        }), 620);
        finishNavigation(760);
        return;
